// total_speedup = 1 / ((1 - p) + p/s)
const amdahl = (p, s) => 1 / ((1 - p) + p / s);
// Candidate A: 70% of time, modest 2x local speedup
// Candidate B: 30% of time, aggressive 8x local speedup
// Candidate C: 70% of time, infinite local speedup (the ceiling)
console.log('A (p=0.7, s=2):', amdahl(0.7, 2).toFixed(2));
console.log('B (p=0.3, s=8):', amdahl(0.3, 8).toFixed(2));
console.log('C (p=0.7, s=Infinity):', amdahl(0.7, Infinity).toFixed(2));

