// Reasoning the team used last time (the trap):
// 1. Microbenchmark: new hash is 10x faster in isolation.
// 2. Therefore the service will be ~10x faster. Ship it.
//
// Rewrite the decision procedure so Amdahl + the profile drive it.

function hottest(samples) {
  // samples: array of stacks; each stack is an array, index 0 = top of stack
  const counts = new Map();
  for (const stack of samples) {
    for (const frame of stack) {
      counts.set(frame, (counts.get(frame) || 0) + 1);
    }
  }
  let best = null, bestN = -1;
  for (const [frame, n] of counts) {
    if (n > bestN) { bestN = n; best = frame; }
  }
  return best;
}

