// candidate: { name, fraction, localSpeedup }  fraction in [0,1]
function pickTarget(candidates) {
  let best = null;
  for (const c of candidates) {
    // estimate the win as fraction * localSpeedup
    c.score = c.fraction * c.localSpeedup;
    if (!best || c.score > best.score) best = c;
  }
  return best;
}

// usage: ranks by score and returns the 'best' target
pickTarget([
  { name: 'serialize', fraction: 0.6, localSpeedup: 2 },
  { name: 'hash',      fraction: 0.1, localSpeedup: 20 },
]);
